'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
require('./mfcc-analysis.js');require('./mel-analysis.js');require('./frequency-analysis.js');
const F=globalThis.FrequencyAnalysis;
const tone=(hz,seconds=1)=>Float32Array.from({length:16000*seconds},(_,i)=>.5*Math.sin(2*Math.PI*hz*i/16000));
const first=tone(500),second=tone(1500),both=new Float32Array(32000);both.set(first);both.set(second,16000);
const result=F.analyze(both,[{startMs:0,endMs:1000},{startMs:1000,endMs:2000}]);
assert.equal(result.chunks[0].peakHz,500);assert.equal(result.chunks[1].peakHz,1500);
assert.deepEqual(result.chunks[0].db,F.spectrum(first).db,'Chunk spectrum must equal isolated audio, including boundary leakage');
assert.deepEqual(result.chunks[1].db,F.spectrum(second).db,'Chunk must not read adjacent audio');
const exact=F.fftPower(first,0,2048);assert.ok(Math.abs(10*Math.log10(exact[64])+6.0206)<.02);
assert.ok(F.spectrum(new Float32Array(16000)).db.every(v=>v===-100));
assert.ok(F.spectrum(tone(500,.04)).db.every(Number.isFinite));
assert.ok(result.whole.db[64]>-12&&result.whole.db[192]>-12);
assert.equal(result.binWidthHz,7.8125);
assert.equal(result.mfcc.coefficientCount,13);
assert.equal(result.mfcc.frames.length,100);
assert.equal(result.mfcc.chunks[0].fingerprint.vector.length,24);
assert.ok(result.mfcc.chunks[0].fingerprint.vector.every(Number.isFinite));
assert.deepEqual(result.mfcc.chunks[0].fingerprint,F.analyze(first,[{startMs:0,endMs:1000}]).mfcc.chunks[0].fingerprint,'Fingerprints must not leak neighboring audio');
const flat=globalThis.MfccAnalysis.coefficients(Array(40).fill(-40));
assert.ok(flat.slice(1).every(v=>Math.abs(v)<1e-10),'Constant log spectrum belongs only to C0');
const shifted=globalThis.MfccAnalysis.coefficients(Array.from({length:40},(_,i)=>-20-i));
const shiftedVolume=globalThis.MfccAnalysis.coefficients(Array.from({length:40},(_,i)=>-30-i));
assert.ok(shifted.slice(1).every((v,i)=>Math.abs(v-shiftedVolume[i+1])<1e-10),'Excluding C0 removes uniform log-power shifts');
assert.equal(F.analyze(new Float32Array(16000),[{startMs:0,endMs:1000}]).mfcc.recordingFingerprint,null,'Closed-only recordings have no active fingerprint');
assert.notDeepEqual(result.mfcc.chunks[0].fingerprint.vector,result.mfcc.chunks[1].fingerprint.vector,'Different tones should have different fingerprints');
assert.equal(result.mel.bands,40);assert.equal(result.mel.frames.length,100);
const strongest=frame=>frame.db.indexOf(Math.max(...frame.db));
assert.ok(strongest(result.mel.frames[0])<strongest(result.mel.frames[50]),'1500 Hz should appear above 500 Hz');
assert.ok(F.analyze(new Float32Array(16000)).mel.frames.every(f=>f.db.every(v=>v===-100)));
const quiet=Float32Array.from(first,v=>v*1e-5);
const closed=F.analyze(quiet,[{startMs:0,endMs:1000,direction:'rising'}]).chunks[0];
assert.equal(closed.chunkType,'closed');assert.ok(closed.averageDb < -90);
assert.equal(closed.direction,'rising');assert.equal(closed.startMs,0);assert.equal(closed.endMs,1000);
assert.equal(F.analyze(first,[{startMs:0,endMs:1000,direction:'stable'}]).chunks[0].chunkType,'stable');
assert.equal(F.analyze(new Float32Array(16000),[{startMs:0,endMs:1000,direction:'stable'}]).chunks[0].chunkType,'closed');
const linearAverage=F.fftPower(first,0,320).slice(1).reduce((a,b)=>a+b,0)/1024;
assert.ok(Math.abs(F.spectrum(first,0,320).averagePower-linearAverage)<1e-12);
const gaps=F.regions([{startMs:100,endMs:300},{startMs:250,endMs:450},{startMs:600,endMs:800}],1000).filter(c=>c.type==='between-chunks');
assert.deepEqual(gaps.map(c=>[c.startMs,c.endMs]),[[0,100],[450,600],[800,1000]]);
assert.equal(F.regions([],1000)[0].type,'between-chunks');
assert.equal(F.regions([{startMs:0,endMs:1000}],1000).length,1);
assert.deepEqual(F.regions([],1000,[{startMs:0,endMs:1000}]),[],'Noise must not become a Between chunks region');
const visible=F.regions([{startMs:100,endMs:300}],1000,[{startMs:0,endMs:100},{startMs:300,endMs:1000}]);
assert.equal(visible.length,1);assert.equal(visible[0].type,'pitch');
assert.equal(F.analyze(first,[],[{startMs:0,endMs:1000}]).regions.length,0);
const withGap=F.analyze(both,[{startMs:0,endMs:1000}]);
assert.equal(withGap.regions[1].type,'between-chunks');assert.equal(withGap.regions[1].peakHz,1500);
// Canvas/UI smoke test without accessing a microphone or audio device.
const strokes=[];
const ctx=new Proxy({stroke(){strokes.push(this.strokeStyle);}},{get:(target,key)=>target[key]||(()=>{})});
const elements=new Map();
const doc={getElementById(id){if(!elements.has(id))elements.set(id,{width:1100,height:300,textContent:'',value:'',options:[],getContext:()=>ctx,setAttribute(k,v){this[k]=v;},replaceChildren(){this.options=[];},add(option){this.options.push(option);}});return elements.get(id);}};
doc.createElement=()=>({width:0,height:0,getContext:()=>ctx});
const sandbox={document:doc,Option:function(text,value){this.text=text;this.value=value;}};
vm.createContext(sandbox);vm.runInContext(fs.readFileSync(__dirname+'/fingerprint-graphs.js','utf8'),sandbox);vm.runInContext(fs.readFileSync(__dirname+'/sound-graphs.js','utf8'),sandbox);
const graphs=new sandbox.SoundGraphs();graphs.set(null,null,null);
graphs.set(both,result,{chunks:[{startMs:0,endMs:1000,direction:'stable'},{startMs:1000,endMs:2000,direction:'rising'}]});
assert.equal(doc.getElementById('fft-chunk').options.length,2);
let callbackTime;graphs.onPosition=ms=>{callbackTime=ms;};
strokes.length=0;graphs.position(1100,1);
assert.equal(callbackTime,1100);assert.equal(strokes.filter(color=>color==='#b33237').length,5,'Waveform, Mel, MFCC and both FFT time strips draw red markers');
assert.match(doc.getElementById('fft-chunk-summary').textContent,/1500 Hz/);
assert.match(doc.getElementById('sound-position').textContent,/1100 ms/);
graphs.set(first,F.analyze(first),null);assert.equal(doc.getElementById('fft-chunk').disabled,false);
assert.match(doc.getElementById('fft-chunk').options[0].text,/Between chunks/);
assert.match(doc.getElementById('fft-full-summary').textContent,/500 Hz/);
console.log('PASS: FFT amplitude, known frequencies, silence, short chunks, chunk isolation and graph controls.');
